28	  eag_marktpraemie: { titel: "EAG-Marktprämie", traeger: "EAG-Förderabwicklungsstelle (OeMAG)", art: "praemie", ebene: "bund", quelle: "EAG §§ 9 ff., § 80; Fachkonzept 1.2", quelleUrl: "https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=20011619", status: "zu_bestaetigen", text: "Laufende Prämie auf eingespeisten Strom (Ausschreibung bzw. Antrag je Technologie). In EEG und BEG nur für die nicht in der Gemeinschaft verbrauchte Menge; laut Fachkonzept für höchstens 50 % der Erzeugung." },
29	  klimafonds: { titel: "Programme des Klima- und Energiefonds", traeger: "Klima- und Energiefonds", art: "programm", ebene: "bund", quelle: "klimafonds.gv.at (z. B. Klima- und Energie-Modellregionen, Leitprojekte; EEG Faktura entstand als KEM-Projekt)", quelleUrl: "https://www.klimafonds.gv.at/", status: "zu_bestaetigen", text: "Jährliche Ausschreibungen für Regionen, Gemeinden und Projekte – häufig für Beratung, Pilotierung und Bürgerbeteiligung. Laufende Calls prüfen." },
30	  umweltfoerderung: { titel: "Umweltförderung im Inland (Betriebe)", traeger: "Kommunalkredit Public Consulting (KPC)", art: "zuschuss", ebene: "bund", quelle: "umweltfoerderung.at", quelleUrl: "https://www.umweltfoerderung.at/", status: "zu_bestaetigen", text: "Förderungen für Betriebe, Vereine und Gemeinden, z. B. Energieeffizienz und Energiemanagement; ob PV bzw. Speicher im konkreten Fall förderfähig sind, hängt von der Förderaktion ab." },
