36	  land_T: { titel: "Energieagentur Tirol", traeger: "Land Tirol", art: "beratung", ebene: "land", land: "T", quelle: "energieagentur.tirol", quelleUrl: "https://www.energieagentur.tirol/", status: "zu_bestaetigen", text: "Beratung und Landesförderungen in Tirol." },
