38	  land_sonst: { titel: "Landesförderung und Energieberatung des Bundeslandes", traeger: "Land", art: "beratung", ebene: "land", quelle: "Ansprechstellen laut Koordinationsstelle", quelleUrl: "https://energiegemeinschaften.gv.at/", status: "zu_bestaetigen", text: "Landesförderungen für PV, Speicher und Energiegemeinschaften wechseln häufig – vor der Planung bei der Landes-Energieberatung prüfen." },
