41	const kategoriePv = (kwp) => EAG_PV_KATEGORIEN.find((k) => kwp <= k.bisKwp) || null;
42	const r1 = (x) => Math.round((Number(x) || 0) * 10) / 10;
43	
44	/**
45	 * Förder-Check.
46	 * @param {{modell?:string, bundesland?:string, antragsteller?:"eg"|"privat"|"landwirt"|"unternehmen"|"gemeinde", gemeindeBeteiligt?:boolean,
47	 *          anlagen?:{art:string, kwp?:number, speicherKwh?:number, status?:"geplant"|"in_bau"|"in_betrieb", bezeichnung?:string}[], stichtag?:string}} d
48	 * @returns {{stand:string, treffer:object[], hinweise:string[], fristen:object[], kennzahlen:object}}
49	 */
50	export function foerderCheck(d = {}) {
51	  const anlagen = (Array.isArray(d.anlagen) ? d.anlagen : []).slice(0, 50).map((a) => ({ art: String(a.art || "pv"), kwp: Math.max(0, Number(a.kwp) || 0), speicherKwh: Math.max(0, Number(a.speicherKwh) || 0), status: ["geplant", "in_bau", "in_betrieb"].includes(a.status) ? a.status : "geplant", bezeichnung: String(a.bezeichnung || "").slice(0, 80) }));
52	  const modell = d.modell || "eeg";
53	  const neuPv = anlagen.filter((a) => a.art === "pv" && a.status !== "in_betrieb");
54	  const altPv = anlagen.filter((a) => a.art === "pv" && a.status === "in_betrieb");
55	  const speicher = anlagen.filter((a) => (a.art === "speicher" || a.speicherKwh > 0) && a.status !== "in_betrieb");
56	  const erzeugend = anlagen.filter((a) => ["pv", "wind", "wasser", "biomasse"].includes(a.art));
57	  const T = [];
58	  const P = (id, ergebnis, gruende, bedingungen = [], naechster = "") => T.push({ id, ...FOERDER_PROGRAMME[id], ergebnis, ergebnisLabel: FOERDER_ERGEBNIS[ergebnis].label, ton: FOERDER_ERGEBNIS[ergebnis].ton, gruende, bedingungen, naechsterSchritt: naechster });
59	
60	  // EAG-Investitionszuschuss PV
61	  if (neuPv.length) {
62	    const passend = neuPv.filter((a) => a.kwp > 0 && a.kwp <= 1000);
63	    const gross = neuPv.filter((a) => a.kwp > 1000);
64	    const gruende = passend.map((a) => `${a.bezeichnung || "PV-Anlage"} ${r1(a.kwp)} kWp → ${kategoriePv(a.kwp).label}`);
65	    if (gross.length) gruende.push(`${gross.length} Anlage(n) über 1.000 kWp – Investitionszuschuss nicht vorgesehen, Marktprämie prüfen (zu bestätigen).`);
66	    P("eag_invest_pv", passend.length ? "pruefen" : "nicht_geeignet", gruende, ["Antrag im Fördercall vor der Bestellung bzw. vor Baubeginn (zu bestätigen)", "Investitionszuschuss und Marktprämie für dieselbe Anlage nicht kombinierbar (zu bestätigen)", "Fördersatz je kWp und Calltermine laut Abwicklungsstelle"], "Calltermine 2026 bei der EAG-Abwicklungsstelle prüfen und Antrag vorbereiten.");
67	  } else if (altPv.length) P("eag_invest_pv", "nicht_geeignet", ["Alle PV-Anlagen sind bereits in Betrieb – ein Investitionszuschuss ist nur für neue Anlagen möglich (zu bestätigen)."]);
68	  else P("eag_invest_pv", "nicht_geeignet", ["Keine geplante PV-Anlage angegeben."]);
69	
70	  // Speicher
71	  if (speicher.length) P("eag_invest_speicher", neuPv.length || anlagen.some((a) => a.art === "pv") ? "pruefen" : "nicht_geeignet", speicher.map((a) => `${a.bezeichnung || "Speicher"} ${r1(a.speicherKwh || a.kwp)} kWh`), ["nur in Verbindung mit einer PV-Anlage (zu bestätigen)", "Mindestverhältnis kWh je kWp laut Call (zu bestätigen)"], "Speichergröße mit der Simulation (WP3) abstimmen.");
72	
73	  // Marktprämie
74	  if (erzeugend.length) {
75	    const g = [];
76	    if (["eeg", "beg"].includes(modell)) g.push("In der Gemeinschaft verbrauchte Mengen erhalten keine Marktprämie – nur der Restüberschuss; laut Fachkonzept höchstens 50 % der Erzeugung.");
77	    if (erzeugend.some((a) => a.art !== "pv")) g.push("Wind, Wasser und Biomasse: Marktprämie je Technologie (Ausschreibung bzw. Antrag).");
78	    if (neuPv.some((a) => a.kwp > 1000)) g.push("Große PV-Anlagen: Marktprämie über Ausschreibung.");
79	    P("eag_marktpraemie", g.length ? "pruefen" : "nicht_geeignet", g.length ? g : ["Für kleine PV-Anlagen ist der Investitionszuschuss der übliche Weg."], ["nicht mit dem Investitionszuschuss derselben Anlage kombinierbar (zu bestätigen)"]);
80	  }
81	
82	  // Klima- und Energiefonds, Umweltförderung, Kommunal
83	  P("klimafonds", "pruefen", [d.gemeindeBeteiligt || d.antragsteller === "gemeinde" ? "Gemeinde beteiligt – Programme für Regionen und Gemeinden (z. B. KEM) prüfen." : "Programme richten sich häufig an Regionen, Gemeinden und Pilotprojekte."], ["Ausschreibungen sind befristet"]);
84	  if (["unternehmen", "landwirt", "gemeinde", "eg"].includes(d.antragsteller || "eg")) P("umweltfoerderung", "pruefen", ["Antragsteller ist Betrieb, Gemeinde bzw. juristische Person – Förderaktionen der Umweltförderung im Inland prüfen."], ["Antrag in der Regel vor Umsetzung (zu bestätigen)"]);
85	  if (d.gemeindeBeteiligt || d.antragsteller === "gemeinde") P("kommunal", "pruefen", ["Gemeinde investiert selbst (z. B. PV auf Gemeindegebäuden für die Gemeinschaft)."], ["Gemeinderatsbeschluss", "fremdübliche Preise in der Gemeinschaft (Beihilferecht, Fachkonzept 2.5)"]);
86	  P("koordinationsstelle", "geeignet", ["Kostenlose Muster und Beratung für jede Gemeinschaft."]);
87	  const landId = `land_${d.bundesland}`;
88	  P(FOERDER_PROGRAMME[landId] ? landId : "land_sonst", "geeignet", [`Landes-Energieberatung${d.bundesland ? "" : " (Bundesland angeben)"} – aktuelle Landesförderungen erfragen.`]);
89	
90	  const hinweise = [
91	    "Förderzusagen gibt nur die Förderstelle. Alle Angaben ohne Gewähr; Fördersätze und Fristen (zu bestätigen).",
92	    "Bei Investitionen der Gemeinschaft: Finanzierung über Mitgliedsbeiträge, Geschäftsanteile (eGen) oder Bürgerbeteiligung prüfen – ÖkoInvest unterstützt Projektierung und Bau über die ÖKOVOLT-Gruppe.",
93	  ];
94	  if (modell === "beg") hinweise.push("BEG: keine Netzentgelt-Reduktion bis 31.12.2026 – die Wirtschaftlichkeit hängt stärker an Förderung und Preisen.");
95	  const fristen = [];
96	  if (neuPv.length) fristen.push({ text: "EAG-Fördercall PV: Termine laut Abwicklungsstelle (zu bestätigen) – Antrag vor Bestellung", quelleUrl: FOERDER_PROGRAMME.eag_invest_pv.quelleUrl });
97	  fristen.push({ text: "Klima- und Energiefonds: laufende Ausschreibungen prüfen", quelleUrl: FOERDER_PROGRAMME.klimafonds.quelleUrl });
98	  return {
99	    stand: FOERDER_STAND, treffer: T, hinweise, fristen,
100	    kennzahlen: { anlagen: anlagen.length, pvNeuKwp: r1(neuPv.reduce((s, a) => s + a.kwp, 0)), speicherKwh: r1(speicher.reduce((s, a) => s + (a.speicherKwh || a.kwp), 0)), geeignet: T.filter((x) => x.ergebnis === "geeignet").length, pruefen: T.filter((x) => x.ergebnis === "pruefen").length },
101	  };
102	}
