121	export function foerderCheck({ land = "DE", typ = "freiflaeche", kwp = 0, eigenverbrauch = false } = {}) {
122	  const reihenfolge = { passt: 0, pruefen: 1, nicht: 2 };
123	  return FOERDERPROGRAMME.filter((p) => p.land === land)
124	    .map((p) => {
125	      let passung = p.passung || (p.immerPruefen ? "pruefen" : "passt");
126	      let grund = "";
127	      if (!p.typen.includes(typ)) {
128	        passung = "nicht";
129	        grund = "Anlagentyp nicht im Programm.";
130	      } else if (p.kwp[0] != null && kwp < p.kwp[0]) {
131	        passung = "nicht";
132	        grund = `Erst ab ${p.kwp[0].toLocaleString("de-DE")} kWp.`;
133	      } else if (p.kwp[1] != null && kwp > p.kwp[1]) {
134	        passung = "nicht";
135	        grund = `Nur bis ${p.kwp[1].toLocaleString("de-DE")} kWp.`;
136	      } else if (p.id === "ch_heiv" && eigenverbrauch) {
137	        passung = "nicht";
138	        grund = "Nur ohne Eigenverbrauch (Volleinspeisung).";
139	      } else if (p.id === "de_eeg" && kwp >= 1000) grund = "Ab 1 MW Teilnahme an der Ausschreibung.";
140	      return { ...p, passung, grund };
141	    })
142	    .sort((a, b) => reihenfolge[a.passung] - reihenfolge[b.passung]);
